sys_atf_step.inputs:
(function(outputs, steps, stepResult) {
  var env = new x_fed_day2_ops.Day2Env();
  if (!env.isTestMode()) {
    stepResult.setFailed('x_fed_day2_ops.test_mode must be true on a declared non-prod instance');
    return;
  }
  stepResult.setSuccess();
})(outputs, steps, stepResult);

(function(outputs, steps, stepResult) {
  var sam = new x_fed_day2_ops.SamCorrelationClient();
  // Same call deny() makes: refused, HTTP 422, opaque reason code.
  var wrote = sam.recordPushOutcome('ATF-SAM-0006', 'refused', 422, 'unverified');
  if (!wrote.ok) { stepResult.setFailed('refusal telemetry write failed: ' + JSON.stringify(wrote)); return; }
  outputs.telemetry_sys_id = wrote.sys_id;
  stepResult.setSuccess();
})(outputs, steps, stepResult);

(function(outputs, steps, stepResult) {
  var gr = new GlideRecord(gs.getProperty('x_fed_day2_ops.tbl_integration', 'x_fed_day2_ops_integration'));
  if (!gr.get(steps('200').telemetry_sys_id)) {
    stepResult.setFailed('could not re-read the telemetry row written in step 200');
    return;
  }
  if (gr.getValue('record_type') !== 'sam_push_outcome') {
    stepResult.setFailed('expected record_type=sam_push_outcome, got ' + gr.getValue('record_type'));
    return;
  }
  if (gr.getValue('sam_request_ref') !== 'ATF-SAM-0006') {
    stepResult.setFailed('telemetry must carry the request id in sam_request_ref; got ' +
                         gr.getValue('sam_request_ref'));
    return;
  }
  var leaked = gr.getValue('sam_request_id');
  if (leaked) {
    stepResult.setFailed('REGRESSION: telemetry wrote sam_request_id=' + leaked +
                         ' — this is the field clause 5 keys on, and it must be reserved ' +
                         'for sam_lineage rows (KIT-BUILD-SPEC.md 2b)');
    return;
  }
  stepResult.setSuccess();
})(outputs, steps, stepResult);

(function(outputs, steps, stepResult) {
  // Verbatim copy of clause 5 in scripted-rest/sam_inbound_ritm.js.
  var existing = new GlideRecord(gs.getProperty('x_fed_day2_ops.tbl_integration', 'x_fed_day2_ops_integration'));
  existing.addQuery('record_type', 'sam_lineage');
  existing.addQuery('sam_request_id', 'ATF-SAM-0006');
  existing.setLimit(1);
  existing.query();

  if (existing.next()) {
    stepResult.setFailed('REGRESSION: clause 5 matched on a request that was only ever REFUSED. ' +
                         'The retry would return 200 {correlated:true, ritm:"' +
                         existing.getValue('ritm') + '"} and no RITM would ever be created.');
    return;
  }
  stepResult.setSuccess();
})(outputs, steps, stepResult);
